import { mapBaseUserToFront } from '@apps/Account/@mappers/user.mappers';
import { IBaseUserDTO } from '@apps/Account/@services/authService';
import { get, handleApiError, post } from '@helpers/httpClient';

import {
  mapWorkoutTargetStatToFront,
  mapWorkoutTargetToFront,
} from '../@mappers/workoutsTargets.mapper';
import {
  IGetWorkoutTargetsCriteria,
  IWorkoutTargetAddDTO,
  IWorkoutTargetDTO,
  IWorkoutTargetStatDTO,
  IWorkoutTargetUpdateDTO,
} from '../@types/DTO/workoutsTargets.dto.types';

export const getWorkoutsTargets = async (criteria: IGetWorkoutTargetsCriteria) => {
  const res = await get('/ajax/workouts/targets/workout_targets_list.php', criteria).then<
    IWorkoutTargetDTO[]
  >(handleApiError);

  return res.map(mapWorkoutTargetToFront);
};

export const getOneWorkoutTargetById = async (id: number) => {
  const res = await get('/ajax/workouts/targets/workout_targets_one.php', {
    id,
  }).then<IWorkoutTargetDTO>(handleApiError);

  return mapWorkoutTargetToFront(res);
};

export const addWorkoutTarget = async (data: IWorkoutTargetAddDTO) => {
  return post('/ajax/workouts/targets/workout_targets_add.php', data).then<{ id: number }>(
    handleApiError,
  );
};

export const updateWorkoutTarget = async (data: IWorkoutTargetUpdateDTO) => {
  return post('/ajax/workouts/targets/workout_targets_edit.php', data).then<{ success: boolean }>(
    handleApiError,
  );
};

export const deleteWorkoutTarget = async (data: { id: number }) => {
  return post('/ajax/workouts/targets/workout_targets_del.php', data).then<{ success: boolean }>(
    handleApiError,
  );
};

export const getWorkoutsTargetStat = async (id_workout_target: number) => {
  const res = await get('/ajax/workouts/targets/workout_targets_stat.php', {
    id_workout_target,
  }).then<IWorkoutTargetStatDTO[]>(handleApiError);

  return res.map(mapWorkoutTargetStatToFront);
};

export const getWorkoutsTargetMembers = async (id_workout_target: number) => {
  const res = await get('/ajax/workouts/targets/workout_targets_members.php', {
    id_workout_target,
  }).then<IBaseUserDTO[]>(handleApiError);

  return res.map(mapBaseUserToFront);
};

export const joinToWorkoutTarget = async (id_workout_target: number) => {
  const res = await post('/ajax/workouts/targets/workout_targets_user_join.php', {
    id_workout_target,
  }).then<{ id: number }>(handleApiError);

  return res.id;
};

export const leaveFromWorkoutTarget = async (id_workout_target: number) => {
  const res = await post('/ajax/workouts/targets/workout_targets_user_leave.php', {
    id_workout_target,
  }).then<{ affected: number }>(handleApiError);

  return res.affected > 0;
};
